import { useAuthStore } from '../store/auth'

const router = createRouter({
  history: createWebHistory(),
  routes: [
    {
      path: '/login',
      name: 'Login',
      component: () => import('../views/LoginView.vue'),
      meta: { requiresAuth: false }
    },
    {
      path: '/',
      redirect: '/dashboard',
      meta: { requiresAuth: true }
    },
    {
      path: '/dashboard',
      name: 'Dashboard',
      component: () => import('../views/DashboardView.vue'),
      meta: { requiresAuth: true }
    },
    {
      path: '/users',
      name: 'Users',
      component: () => import('../views/UsersView.vue'),
      meta: { requiresAuth: true, role: 'ADMIN' }
    },
    {
      path: '/market-events',
      name: 'MarketEvents',
      component: () => import('../views/MarketEventsView.vue'),
      meta: { requiresAuth: true, role: 'ADMIN' }
    },
    {
      path: '/booths',
      name: 'Booths',
      component: () => import('../views/BoothsView.vue'),
      meta: { requiresAuth: true }
    },
    {
      path: '/applications',
      name: 'Applications',
      component: () => import('../views/ApplicationsView.vue'),
      meta: { requiresAuth: true, role: 'ADMIN' }
    },
    {
      path: '/orders',
      name: 'Orders',
      component: () => import('../views/OrdersView.vue'),
      meta: { requiresAuth: true }
    },
    {
      path: '/statistics',
      name: 'Statistics',
      component: () => import('../views/StatisticsView.vue'),
      meta: { requiresAuth: true, role: 'ADMIN' }
    }
  ]
})

// 路由守卫
router.beforeEach((to, from, next) => {
  const authStore = useAuthStore()

  if (to.meta.requiresAuth && !authStore.isAuthenticated) {
    next('/login')
    return
  }

  // 检查角色权限
  if (to.meta.role && authStore.user?.role !== to.meta.role) {
    next('/dashboard')
    return
  }

  next()
})

export default router"}, name='run_write', type='tool_use', toolset_name=None)

ToolUseBlock(id='call_d00f8dd8816845f692498870', caller=None, input={'path': 'craft-market-frontend/src/utils/http.js', 'content': "import axios from 'axios'
import { useAuthStore } from '../store/auth'

// 创建axios实例
const http = axios.create({
  baseURL: '/api',
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json'
  }
})

// 请求拦截器
http.interceptors.request.use(
  (config) => {
    const authStore = useAuthStore()
    const token = authStore.token

    if (token) {
      config.headers.Authorization = `Bearer ${token}`
    }

    return config
  },
  (error) => {
    return Promise.reject(error)
  }
)

// 响应拦截器
http.interceptors.response.use(
  (response) => {
    const data = response.data

    // 处理统一响应格式
    if (data.code === 200) {
      return data
    } else {
      // 业务错误
      throw new Error(data.message || '操作失败')
    }
  },
  (error) => {
    const authStore = useAuthStore()

    if (error.response) {
      const { status } = error.response

      switch (status) {
        case 401:
          authStore.logout()
          throw new Error('登录已过期，请重新登录')
        case 403:
          throw new Error('权限不足')
        case 404:
          throw new Error('资源不存在')
        case 500:
          throw new Error('服务器内部错误')
        default:
          throw new Error(error.response.data.message || '请求失败')
      }
    } else if (error.code === 'ECONNABORTED') {
      throw new Error('请求超时')
    } else {
      throw new Error('网络错误')
    }
  }
)

export default http"}, name='run_write', type='tool_use', toolset_name=None)

ToolUseBlock(id='call_8ceacf221b9244f4a60e61a0', caller=None, input={'path': 'craft-market-frontend/src/store/auth.js', 'content': "import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import http from '../utils/http'

export const useAuthStore = defineStore('auth', () => {
  const token = ref(localStorage.getItem('token') || '')
  const user = ref(null)

  const isAuthenticated = computed(() => !!token.value)
  const isAdmin = computed(() => user.value?.role === 'ADMIN')

  // 登录
  const login = async (username, password) => {
    try {
      const response = await http.post('/auth/login', {
        username,
        password
      })

      token.value = response.data.token
      user.value = response.data.user

      // 保存token到本地存储
      localStorage.setItem('token', token.value)

      return response.data
    } catch (error) {
      throw error
    }
  }

  // 登出
  const logout = () => {
    token.value = ''
    user.value = null
    localStorage.removeItem('token')
  }

  // 获取用户信息
  const getUserInfo = async () => {
    try {
      const response = await http.get('/auth/user')
      user.value = response.data
      return response.data
    } catch (error) {
      throw error
    }
  }

  // 更新用户信息
  const updateUserInfo = async (userData) => {
    try {
      const response = await http.put('/auth/user', userData)
      user.value = response.data
      return response.data
    } catch (error) {
      throw error
    }
  }

  return {
    token,
    user,
    isAuthenticated,
    isAdmin,
    login,
    logout,
    getUserInfo,
    updateUserInfo
  }
})"}, name='run_write', type='tool_use', toolset_name=None)

